import numpy as np
z=np.load('/app/output/live_state.npz');P=z['Jp'];R=z['Jr'];d=np.array([-.0824,.0146,-.0249]);
for a in [0,.02,.05,.1,.2,.4,1]:
 for lam in [.01,.05,.1]:
  dq=np.linalg.solve(P.T@P+a*a*R.T@R+lam*lam*np.eye(7),P.T@d)
  dp=P@dq;dw=R@dq
  print('a',a,'l',lam,'qmax',round(max(abs(dq)),3),'dp',np.round(dp,3),'dwdeg',np.round(dw*180/np.pi,1),'qnorm',round(np.linalg.norm(dq),3))
 print()
PY

